import Foundation
import Testing
@testable import ArborCore

/// FE-152: MP3, FLAC and M4A round trips. Generated bytes in disposable folders; "Trash" is a folder inside the fixture.
@Suite struct AudioMetadataTests {
    private typealias F = AudioFixtures

    private func write(_ bytes: Data, _ name: String, in fixture: Fixture) throws -> URL {
        let url = fixture.url(name)
        try bytes.write(to: url)
        return url
    }

    private func read(_ url: URL) throws -> EmbeddedSnapshot { try #require(EmbeddedSnapshot.read(url)) }

    @discardableResult
    private func save(_ edits: [EmbeddedField: String], _ url: URL, in fixture: Fixture) throws -> EmbeddedMetadataEditor.Revert {
        try EmbeddedMetadataEditor.save(edits, over: try read(url), dispose: F.dispose(into: fixture))
    }

    private func contains(_ haystack: Data, _ needle: Data) -> Bool { haystack.range(of: needle) != nil }

    private let allEdits: [EmbeddedField: String] = [.title: "New title – 写真 🌳", .artist: "Ünï Çödé", .album: "New album", .year: "2021", .track: "3/12",
                                                     .genre: "Rock", .comment: "New comment\nsecond line"]

    private func expectAllEdits(_ url: URL) throws {
        let after = try read(url)
        for (field, value) in allEdits { #expect(after.values[field] == value, "\(field)") }
    }

    // MARK: MP3

    @Test func id3v23RoundTripsInUTF16AndKeepsEverythingElse() throws {
        let fixture = try Fixture()
        let original = F.mp3()
        let url = try write(original, "a.mp3", in: fixture)
        let before = try read(url)
        #expect(before.typeIdentifier == ID3Format.identifier)
        #expect(before.blocked == nil)
        #expect(before.values[.title] == "Old title")
        #expect(before.values[.comment] == "Old comment")
        #expect(before.editable == [.title, .artist, .album, .year, .track, .genre, .comment])

        try save(allEdits, url, in: fixture)
        try expectAllEdits(url)
        let written = try Data(contentsOf: url)
        #expect(contains(written, Data([1, 0xFF, 0xFE, UInt8(ascii: "N"), 0])))
        #expect(contains(written, "写真".utf16.reduce(into: Data()) { $0 += [UInt8($1 & 255), UInt8($1 >> 8)] }))
        for kept in [F.picture, F.privateFrame, F.unknownFrame, F.iTunesComment] { #expect(contains(written, kept)) }
        #expect(written.suffix(F.mpegAudio.count + F.id3v1.count) == F.mpegAudio + F.id3v1)
        // The comment keeps its language.
        #expect(contains(written, Data("COMM".utf8)) && contains(written, Data("deu".utf8)))
    }

    @Test func id3v24RoundTripsInUTF8() throws {
        let fixture = try Fixture()
        let frames = [F.utf8("TIT2", "Old"), F.utf8("TDRC", "1999"), F.frame("PRIV", Data("o\0".utf8) + [1], version: 4)]
        let url = try write(F.mp3(frames, version: 4, trailer: Data()), "a.mp3", in: fixture)
        #expect(try read(url).values[.year] == "1999")
        try save([.title: "写真 🌳", .year: "2005"], url, in: fixture)
        let after = try read(url)
        #expect(after.values[.title] == "写真 🌳")
        #expect(after.values[.year] == "2005")
        let written = try Data(contentsOf: url)
        #expect(contains(written, Data([3]) + Data("写真 🌳".utf8)))
        #expect(contains(written, F.frame("PRIV", Data("o\0".utf8) + [1], version: 4)))
    }

    @Test func clearingAFieldRemovesItsFrameAlone() throws {
        let fixture = try Fixture()
        let url = try write(F.mp3(), "a.mp3", in: fixture)
        try save([.title: "", .comment: ""], url, in: fixture)
        let after = try read(url)
        #expect(after.values[.title] == nil)
        #expect(after.values[.comment] == nil)
        #expect(after.values[.artist] == "Old artist")
        #expect(contains(try Data(contentsOf: url), F.iTunesComment))
    }

    @Test func framesThatFitLeaveTheAudioWhereItWas() throws {
        let fixture = try Fixture()
        let original = F.mp3()
        let url = try write(original, "a.mp3", in: fixture)
        try save([.title: "Short"], url, in: fixture)
        #expect(try Data(contentsOf: url).count == original.count)
    }

    @Test func aLargerTagMovesTheAudioIntact() throws {
        let fixture = try Fixture()
        let url = try write(F.mp3(padding: 0), "a.mp3", in: fixture)
        let long = String(repeating: "long ", count: 100)
        try save([.title: long], url, in: fixture)
        #expect(try read(url).values[.title] == long)
        #expect(try Data(contentsOf: url).suffix(F.mpegAudio.count + F.id3v1.count) == F.mpegAudio + F.id3v1)
    }

    @Test func addsFramesThatWereNotThere() throws {
        let fixture = try Fixture()
        let url = try write(F.mp3([F.latin1("TIT2", "Only")], padding: 0, trailer: Data()), "a.mp3", in: fixture)
        try save([.album: "New album", .comment: "写"], url, in: fixture)
        let after = try read(url)
        #expect(after.values[.title] == "Only")
        #expect(after.values[.album] == "New album")
        #expect(after.values[.comment] == "写")
    }

    @Test func numberedGenresShowTheirNameAndAreLeftAloneUntilChanged() throws {
        let fixture = try Fixture()
        let url = try write(F.mp3([F.latin1("TCON", "(17)"), F.latin1("TIT2", "T")]), "a.mp3", in: fixture)
        let before = try read(url)
        #expect(before.values[.genre] == "Rock")
        #expect(before.editable.contains(.genre))
        #expect(try EmbeddedEdits.make(from: [.genre: "Rock"], snapshot: before).isEmpty)
        try save([.title: "U"], url, in: fixture)
        #expect(contains(try Data(contentsOf: url), Data("(17)".utf8)))
        let mixed = try write(F.mp3([F.latin1("TCON", "(17)(21)Eurodisco")]), "b.mp3", in: fixture)
        #expect(try read(mixed).editable.contains(.genre) == false)
    }

    @Test func repeatedOrMultiValueFramesAreShownButNotOffered() throws {
        let fixture = try Fixture()
        let twice = try write(F.mp3([F.latin1("TIT2", "A"), F.latin1("TIT2", "B")]), "a.mp3", in: fixture)
        #expect(try read(twice).values[.title] == "A")
        #expect(try read(twice).editable.contains(.title) == false)
        let many = try write(F.mp3([F.frame("TPE1", Data([3]) + Data("A\0B".utf8), version: 4)], version: 4), "b.mp3", in: fixture)
        #expect(try read(many).values[.artist] == "A; B")
        #expect(try read(many).editable.contains(.artist) == false)
        let readOnlyFrame = try write(F.mp3([F.frame("TIT2", Data([0]) + Data("T".utf8), flags: [0x20, 0])]), "c.mp3", in: fixture)
        #expect(try read(readOnlyFrame).editable.contains(.title) == false)
    }

    @Test func theOtherVersionsYearFrameIsShownButNotOffered() throws {
        let fixture = try Fixture()
        let url = try write(F.mp3([F.frame("TDRC", Data([0]) + Data("2001-05".utf8))]), "a.mp3", in: fixture)
        #expect(try read(url).values[.year] == "2001-05")
        #expect(try read(url).editable.contains(.year) == false)
    }

    @Test(arguments: [
        (UInt8(3), UInt8(0x80), "unsynchronised"), (3, 0x40, "extended header"), (4, 0x10, "footer"), (4, 0x80, "unsynchronised"),
    ])
    func tagFeaturesMakeTheFileReadOnlyWithTheReason(version: UInt8, flags: UInt8, reason: String) throws {
        let fixture = try Fixture()
        let url = try write(F.mp3([F.latin1("TIT2", "T", version: version)], version: version, flags: flags), "a.mp3", in: fixture)
        let snapshot = try read(url)
        #expect(snapshot.editable.isEmpty)
        #expect(snapshot.blocked?.localizedDescription.contains(reason) == true)
    }

    @Test(arguments: [([UInt8(0), 0x80], "compressed"), ([0, 0x40], "encrypted")])
    func compressedOrEncryptedFramesMakeTheFileReadOnly(flags: [UInt8], reason: String) throws {
        let fixture = try Fixture()
        let url = try write(F.mp3([F.frame("TXXX", Data([0, 1, 2, 3, 4]), flags: flags), F.latin1("TIT2", "T")]), "a.mp3", in: fixture)
        #expect(try read(url).blocked?.localizedDescription.contains(reason) == true)
    }

    @Test func aSecondTagMakesTheFileReadOnly() throws {
        let fixture = try Fixture()
        let doubled = F.tag([F.latin1("TIT2", "A")]) + F.tag([F.latin1("TIT2", "B")]) + F.mpegAudio
        let url = try write(doubled, "a.mp3", in: fixture)
        #expect(try read(url).blocked?.localizedDescription.contains("more than one tag") == true)
        let seek = try write(F.mp3([F.frame("SEEK", Data(count: 4), version: 4)], version: 4), "b.mp3", in: fixture)
        #expect(try read(seek).blocked != nil)
        let appended = F.tag([F.latin1("TIT2", "A")]) + F.mpegAudio + Data("3DI".utf8) + [4, 0, 0x10, 0, 0, 0, 0]
        let footerAtEnd = try write(appended, "c.mp3", in: fixture)
        #expect(try read(footerAtEnd).blocked?.localizedDescription.contains("more than one tag") == true)
    }

    @Test func olderID3VersionsAreReadOnlyWithAReason() throws {
        let fixture = try Fixture()
        let url = try write(Data("ID3".utf8) + [2, 0, 0, 0, 0, 0, 0] + F.mpegAudio, "a.mp3", in: fixture)
        #expect(try read(url).blocked?.localizedDescription.contains("ID3 version") == true)
    }

    @Test func aFileWithoutATagIsNotOffered() throws {
        let fixture = try Fixture()
        #expect(EmbeddedSnapshot.read(try write(F.mpegAudio, "a.mp3", in: fixture)) == nil)
    }

    // MARK: FLAC

    @Test func flacCommentsRoundTripAndEverythingElseSurvives() throws {
        let fixture = try Fixture()
        let original = F.flac()
        let url = try write(original, "a.flac", in: fixture)
        #expect(try read(url).typeIdentifier == FLACFormat.identifier)
        try save(allEdits, url, in: fixture)
        try expectAllEdits(url)
        let written = try Data(contentsOf: url)
        #expect(written.prefix(4 + F.streamInfo.count) == original.prefix(4 + F.streamInfo.count))
        #expect(contains(written, Data(F.vendor.utf8)))
        for kept in F.plainComments.suffix(2) { #expect(contains(written, F.le32(kept.utf8.count) + Data(kept.utf8))) }
        #expect(written.suffix(F.otherBlocks.count + 12 + F.flacFrames.count) == F.otherBlocks + F.block(1, Data(count: 8), last: true) + F.flacFrames)
    }

    @Test func flacKeepsTheKeysOwnSpellingAndAddsMissingComments() throws {
        let fixture = try Fixture()
        let url = try write(F.flac(["Title=Old", "CUSTOM=x"]), "a.flac", in: fixture)
        try save([.title: "New", .genre: "Rock", .album: ""], url, in: fixture)
        let written = try Data(contentsOf: url)
        #expect(contains(written, Data("Title=New".utf8)))
        #expect(contains(written, Data("GENRE=Rock".utf8)))
        #expect(contains(written, Data("CUSTOM=x".utf8)))
    }

    @Test func aFlacCommentWhoseLengthBytesHoldAnEqualsSignCanBeEdited() throws {
        let fixture = try Fixture()
        // Lengths 61, 317 and 15616 put 0x3D in the first or second byte of the little-endian prefix.
        let cases: [(EmbeddedField, String)] = [(.title, "TITLE=" + String(repeating: "x", count: 55)), (.title, "Title=" + String(repeating: "x", count: 311)),
                                                (.comment, "COMMENT=" + String(repeating: "🌳", count: 3902))]
        for (index, (field, comment)) in cases.enumerated() {
            let url = try write(F.flac([comment, "ALBUM=Kept"]), "\(index).flac", in: fixture)
            try save([field: "New"], url, in: fixture)
            let key = comment.prefix { $0 != "=" }
            let written = try Data(contentsOf: url)
            #expect(contains(written, F.le32(key.utf8.count + 4) + Data("\(key)=New".utf8)))
            #expect(contains(written, F.le32(10) + Data("ALBUM=Kept".utf8)))
        }
    }

    @Test func clearingAFlacCommentRemovesOnlyThatOne() throws {
        let fixture = try Fixture()
        let url = try write(F.flac(), "a.flac", in: fixture)
        try save([.artist: ""], url, in: fixture)
        let after = try read(url)
        #expect(after.values[.artist] == nil)
        #expect(after.values[.title] == "Old title")
    }

    @Test func multiValueFlacCommentsAreShownButNotOffered() throws {
        let fixture = try Fixture()
        let url = try write(F.flac(["ARTIST=A", "artist=B", "TITLE=T"]), "a.flac", in: fixture)
        let snapshot = try read(url)
        #expect(snapshot.values[.artist] == "A")
        #expect(!snapshot.editable.contains(.artist))
        #expect(snapshot.editable.contains(.title))
    }

    @Test func flacWithoutOrWithTwoCommentBlocksIsReadOnly() throws {
        let fixture = try Fixture()
        let none = Data("fLaC".utf8) + F.block(0, Data(repeating: 1, count: 34), last: true) + F.flacFrames
        #expect(try read(try write(none, "a.flac", in: fixture)).blocked?.localizedDescription.contains("no comment block") == true)
        let two = Data("fLaC".utf8) + F.streamInfo + F.block(4, F.comments([])) + F.block(4, F.comments([]), last: true) + F.flacFrames
        #expect(try read(try write(two, "b.flac", in: fixture)).blocked?.localizedDescription.contains("more than one") == true)
    }

    @Test func realFlacKeepsItsSound() throws {
        let fixture = try Fixture()
        let url = try F.real("flac", "flac", name: "real.flac", in: fixture)
        let sound = try F.decoded(url, in: fixture)
        #expect(try read(url).blocked == nil)
        try save([.title: "写真 🌳", .artist: "Someone", .track: "2"], url, in: fixture)
        #expect(try read(url).values[.title] == "写真 🌳")
        #expect(try F.decoded(url, in: fixture) == sound)
    }

    // MARK: M4A

    @Test func realM4AWritesIntoTheFreeSpaceAndNeverMovesTheAudio() throws {
        let fixture = try Fixture()
        let url = try F.real("m4af", "aac", name: "real.m4a", in: fixture)
        let original = try Data(contentsOf: url)
        let sound = try F.decoded(url, in: fixture)
        let snapshot = try read(url)
        #expect(snapshot.typeIdentifier == M4AFormat.identifier)
        #expect(snapshot.blocked == nil)
        try save(allEdits, url, in: fixture)
        try expectAllEdits(url)
        let written = try Data(contentsOf: url)
        #expect(written.count == original.count)
        let audio = try #require(original.range(of: Data("mdat".utf8)))
        #expect(written.range(of: Data("mdat".utf8)) == audio)
        #expect(written[audio.lowerBound...] == original[audio.lowerBound...])
        #expect(contains(written, Data("iTunSMPB".utf8)))
        #expect(try F.decoded(url, in: fixture) == sound)
    }

    @Test func m4aWithTheIndexLastMayGrow() throws {
        let fixture = try Fixture()
        let original = F.m4aIndexLast()
        let url = try write(original, "a.m4a", in: fixture)
        try save(allEdits, url, in: fixture)
        try expectAllEdits(url)
        let written = try Data(contentsOf: url)
        let head = F.ftyp.count + F.media.count
        #expect(written.prefix(head) == original.prefix(head))
        for kept in [F.customItem, F.coverItem, F.unknownItem, F.atom("chpl", Data([1, 2, 3])), F.atom("wxyz", Data([4, 5]))] { #expect(contains(written, kept)) }
    }

    @Test func clearingAnM4AValueGivesItsSpaceBackToTheFreeAtom() throws {
        let fixture = try Fixture()
        let url = try write(F.m4aIndexFirst(), "a.m4a", in: fixture)
        let size = try Data(contentsOf: url).count
        try save([.comment: "", .album: ""], url, in: fixture)
        let after = try read(url)
        #expect(after.values[.comment] == nil)
        #expect(after.values[.album] == nil)
        #expect(after.values[.title] == "Old title")
        #expect(try Data(contentsOf: url).count == size)
    }

    @Test func m4aPrefersFreeSpaceInsideTheMetadata() throws {
        let fixture = try Fixture()
        let original = F.m4aIndexFirst(topFree: 0, metaFree: 256)
        let url = try write(original, "a.m4a", in: fixture)
        try save([.title: "A longer title than before"], url, in: fixture)
        let written = try Data(contentsOf: url)
        #expect(written.count == original.count)
        #expect(written.suffix(F.media.count) == F.media)
        #expect(try read(url).values[.title] == "A longer title than before")
    }

    @Test func m4aWithNoFreeSpaceBesideItsMetadataIsReadOnly() throws {
        let fixture = try Fixture()
        let url = try write(F.m4aIndexFirst(topFree: 0), "a.m4a", in: fixture)
        let snapshot = try read(url)
        #expect(snapshot.editable.isEmpty)
        #expect(snapshot.blocked?.localizedDescription.contains("free space") == true)
        #expect(snapshot.values[.title] == "Old title")
    }

    @Test func tooLittleFreeSpaceRefusesTheSaveAndKeepsTheFile() throws {
        let fixture = try Fixture()
        let url = try write(F.m4aIndexFirst(topFree: 16), "a.m4a", in: fixture)
        let before = try Data(contentsOf: url)
        #expect(throws: EmbeddedFailure.noRoomBesideMetadata) {
            try save([.title: String(repeating: "x", count: 200)], url, in: fixture)
        }
        #expect(try Data(contentsOf: url) == before)
        #expect(fixture.names(".fixture-trash").isEmpty)
    }

    @Test func numericGenreAndTrackAtomsAreRead() throws {
        let fixture = try Fixture()
        let genre = F.atom("gnre", F.atom("data", F.be32(0) + F.be32(0) + Data([0, 18])))
        let url = try write(F.m4aIndexLast(items: [genre]), "a.m4a", in: fixture)
        #expect(try read(url).values[.genre] == "Rock")
        try save([.genre: "Jazz", .track: "4"], url, in: fixture)
        let after = try read(url)
        #expect(after.values[.genre] == "Jazz")
        #expect(after.values[.track] == "4")
        #expect(!contains(try Data(contentsOf: url), Data("gnre".utf8)))
    }

    @Test func multipleValuesInAnAtomAreNotOffered() throws {
        let fixture = try Fixture()
        let double = F.atom("\u{A9}ART", F.atom("data", F.be32(1) + F.be32(0) + Data("A".utf8)) + F.atom("data", F.be32(1) + F.be32(0) + Data("B".utf8)))
        let snapshot = try read(try write(F.m4aIndexLast(items: [double]), "a.m4a", in: fixture))
        #expect(!snapshot.editable.contains(.artist))
        #expect(snapshot.editable.contains(.title))
    }

    @Test func videoIsNotOfferedAsAudio() throws {
        let fixture = try Fixture()
        let url = try write(F.ftyp + F.media + F.moov(handler: "vide"), "a.mp4", in: fixture)
        #expect(EmbeddedSnapshot.read(url) == nil)
    }

    private static let openBrand = F.atom("ftyp", F.type("isom") + F.be32(0) + F.type("isom"))
    private static let cutOffMedia = F.be32(0x7FFF_FFFF) + F.type("mdat") + Data(count: 16)
    private static let manyFragments = (0..<5000).reduce(into: Data()) { list, _ in list += F.atom("moof", Data()) }

    @Test func anOpenBrandFileThatCantBeProvenAudioIsNotCalledADamagedM4A() throws {
        let fixture = try Fixture()
        let brand = Self.openBrand, cutOff = Self.cutOffMedia
        let unwalkableIndex = F.atom("moov", F.be32(0x7FFF_FFFF) + F.type("trak") + Data(count: 8))
        for (index, bytes) in [brand + cutOff, brand + F.moov(handler: "vide") + cutOff, brand + F.moov(handler: "vide") + Self.manyFragments,
                               brand + F.moov() + F.moov(), brand + unwalkableIndex].enumerated() {
            #expect(EmbeddedSnapshot.read(try write(bytes, "\(index).mp4", in: fixture)) == nil, "\(index)")
        }
    }

    @Test func audioThatCantBeWalkedToTheEndIsReadOnlyWithAReason() throws {
        let fixture = try Fixture()
        let proven = try read(try write(Self.openBrand + F.moov() + Self.cutOffMedia, "a.m4a", in: fixture))
        #expect(proven.typeIdentifier == M4AFormat.identifier)
        #expect(proven.blocked?.localizedDescription.contains("damaged") == true)
        let namedByItsBrand = try read(try write(F.ftyp + Self.cutOffMedia, "b.m4a", in: fixture))
        #expect(namedByItsBrand.blocked?.localizedDescription.contains("damaged") == true)
        let fragments = try read(try write(Self.openBrand + F.moov() + Self.manyFragments, "c.m4a", in: fixture))
        #expect(fragments.blocked?.localizedDescription.contains("fragmented") == true)
    }

    @Test func fragmentedM4AIsReadOnly() throws {
        let fixture = try Fixture()
        let url = try write(F.m4aIndexLast() + F.atom("moof", Data(count: 8)), "a.m4a", in: fixture)
        #expect(try read(url).blocked?.localizedDescription.contains("fragmented") == true)
    }

    @Test func m4aWithoutAMetadataListIsReadOnly() throws {
        let fixture = try Fixture()
        let bare = F.ftyp + F.media + F.atom("moov", F.atom("trak", F.atom("mdia", F.atom("hdlr", F.handler("soun")))))
        #expect(try read(try write(bare, "a.m4a", in: fixture)).blocked?.localizedDescription.contains("metadata list") == true)
    }

    @Test func aQuickTimeBrandIsNotOffered() throws {
        let fixture = try Fixture()
        let quickTime = F.atom("ftyp", F.type("qt  ") + F.be32(0)) + F.media + F.moov()
        #expect(EmbeddedSnapshot.read(try write(quickTime, "a.mov", in: fixture)) == nil)
    }

    // MARK: The pipeline they share

    @Test(arguments: [("a.mp3", F.mp3()), ("a.flac", F.flac()), ("a.m4a", F.m4aIndexFirst())])
    func editThenUndoRestoresEveryByteAndRedoTheEdit(name: String, original: Data) throws {
        let fixture = try Fixture()
        let url = try write(original, name, in: fixture)
        let step = try save([.title: "Edited"], url, in: fixture)
        let edited = try Data(contentsOf: url)
        #expect(edited != original)
        #expect(try Data(contentsOf: step.kept) == original)
        let opposite = try EmbeddedMetadataEditor.revert(step)
        #expect(try Data(contentsOf: url) == original)
        #expect(try read(url).values[.title] == "Old title")
        _ = try EmbeddedMetadataEditor.revert(opposite)
        #expect(try Data(contentsOf: url) == edited)
    }

    @Test(arguments: [("a.mp3", F.mp3()), ("a.flac", F.flac()), ("a.m4a", F.m4aIndexFirst())])
    func refusesAFileChangedSinceItWasRead(name: String, original: Data) throws {
        let fixture = try Fixture()
        let url = try write(original, name, in: fixture)
        let snapshot = try read(url)
        try FileManager.default.setAttributes([.modificationDate: Date(timeIntervalSinceNow: 60)], ofItemAtPath: url.path)
        #expect(throws: EmbeddedFailure.changedSinceRead) {
            try EmbeddedMetadataEditor.save([.title: "Nope"], over: snapshot, dispose: F.dispose(into: fixture))
        }
        #expect(try Data(contentsOf: url) == original)
        #expect(fixture.names(".fixture-trash").isEmpty)
    }

    @Test func noStagingFilesAreLeftBesideAndAttributesAreKept() throws {
        let fixture = try Fixture()
        let folder = try fixture.folder("music")
        let url = try write(F.flac(), "music/a.flac", in: fixture)
        try FileManager.default.setAttributes([.posixPermissions: 0o640], ofItemAtPath: url.path)
        try FinderMetadata.setComment("keep", on: url)
        try save([.title: "T"], url, in: fixture)
        #expect(try FileManager.default.contentsOfDirectory(atPath: folder.path) == ["a.flac"])
        #expect((try FileManager.default.attributesOfItem(atPath: url.path)[.posixPermissions] as? NSNumber)?.intValue == 0o640)
        #expect(FinderMetadata.comment(of: url) == "keep")
    }

    @Test func hardLinksAndLockedFilesAreBlockedLikeImages() throws {
        let fixture = try Fixture()
        let linked = try write(F.mp3(), "a.mp3", in: fixture)
        try FileManager.default.linkItem(at: linked, to: fixture.url("b.mp3"))
        #expect(try read(linked).blocked == .hardLinked)
        let locked = try write(F.flac(), "c.flac", in: fixture)
        try FileManager.default.setAttributes([.immutable: true], ofItemAtPath: locked.path)
        defer { try? FileManager.default.setAttributes([.immutable: false], ofItemAtPath: locked.path) }
        #expect(try read(locked).blocked == .locked)
    }

    // MARK: Validation

    @Test func yearAndTrackAreValidated() throws {
        let fixture = try Fixture()
        let snapshot = try read(try write(F.mp3(), "a.mp3", in: fixture))
        #expect(try EmbeddedEdits.make(from: [.year: "1999", .track: "1/9"], snapshot: snapshot).isEmpty)
        #expect(try EmbeddedEdits.make(from: [.year: "2024", .track: "03"], snapshot: snapshot) == [.year: "2024", .track: "3"])
        for bad in ["abcd", "99", "20245", "٢٠٢٤"] {
            #expect(throws: EmbeddedFailure.self) { try EmbeddedEdits.make(from: [.year: bad], snapshot: snapshot) }
        }
        for bad in ["x", "0", "3/0", "3/", "/3", "1/2/3", "70000"] {
            #expect(throws: EmbeddedFailure.self) { try EmbeddedEdits.make(from: [.track: bad], snapshot: snapshot) }
        }
        for bad in ["17", "(17)"] {
            #expect(throws: EmbeddedFailure.self) { try EmbeddedEdits.make(from: [.genre: bad], snapshot: snapshot) }
        }
        #expect(throws: EmbeddedFailure.self) { try EmbeddedEdits.make(from: [.artist: "a\u{0}b"], snapshot: snapshot) }
    }

    @Test func anUntouchedYearOrTrackWithStraySpacesIsNotAnEdit() throws {
        let fixture = try Fixture()
        let url = try write(F.flac(["DATE=2001 ", "TRACKNUMBER= 3", "TITLE=T"]), "a.flac", in: fixture)
        let padded = try read(url)
        #expect(padded.editable.isSuperset(of: [.year, .track]))
        let edits = try EmbeddedEdits.make(from: [.year: "2001 ", .track: " 3", .title: "New"], snapshot: padded)
        #expect(edits == [.title: "New"])
        try save(edits, url, in: fixture)
        let written = try Data(contentsOf: url)
        #expect(contains(written, Data("DATE=2001 ".utf8)) && contains(written, Data("TRACKNUMBER= 3".utf8)))

        let unusual = try read(try write(F.flac(["DATE=2001-05 ", "TRACKNUMBER=A1 ", "TITLE=T"]), "b.flac", in: fixture))
        #expect(try EmbeddedEdits.make(from: [.year: "2001-05 ", .track: "A1 ", .title: "New"], snapshot: unusual) == [.title: "New"])

        // What the user does change is still checked and tidied.
        #expect(try EmbeddedEdits.make(from: [.year: "2002 ", .track: " 4"], snapshot: padded) == [.year: "2002", .track: "4"])
        #expect(throws: EmbeddedFailure.self) { try EmbeddedEdits.make(from: [.year: "2001-06 "], snapshot: unusual) }
        #expect(throws: EmbeddedFailure.self) { try EmbeddedEdits.make(from: [.track: "A2 "], snapshot: unusual) }
    }

    @Test func aFullDateIsKeptUntilItIsChanged() throws {
        let fixture = try Fixture()
        let snapshot = try read(try write(F.flac(["DATE=2001-05-06", "TITLE=T"]), "a.flac", in: fixture))
        #expect(snapshot.values[.year] == "2001-05-06")
        #expect(try EmbeddedEdits.make(from: [.year: "2001-05-06"], snapshot: snapshot).isEmpty)
        #expect(try EmbeddedEdits.make(from: [.year: "2002"], snapshot: snapshot) == [.year: "2002"])
    }

    @Test func auditListsTheFieldsAudioCanTake() {
        for type in [ID3Format.identifier, FLACFormat.identifier, M4AFormat.identifier] {
            #expect(EmbeddedSupport.forType(type)?.fields == [.title, .artist, .album, .year, .track, .genre, .comment])
            #expect(EmbeddedSupport.forType(type)?.isAudio == true)
        }
    }
}
